python3 -c "
import json
with open('/app/dialogue.json') as f:
    graph = json.load(f)

nodes = graph['nodes']
edges = graph['edges']
node_ids = {n['id'] for n in nodes}
edge_targets = {e['to'] for e in edges}

print(f'Total nodes: {len(nodes)}')
print(f'Total edges: {len(edges)}')
print(f'Node types: line={sum(1 for n in nodes if n[\"type\"]==\"line\")}, choice={sum(1 for n in nodes if n[\"type\"]==\"choice\")}')

# Check for End node
print(f\"End node exists: {'End' in node_ids}\")

# Check edge targets
missing = edge_targets - node_ids
if missing:
    print(f'Missing targets: {missing}')
else:
    print('All edge targets exist')

# Check reachability
adj = {n['id']: [] for n in nodes}
for e in edges:
    if e['from'] in adj:
        adj[e['from']].append(e['to'])

visited = set()
queue = ['Start']
while queue:
    cur = queue.pop(0)
    if cur in visited:
        continue
    visited.add(cur)
    for neighbor in adj.get(cur, []):
        if neighbor not in visited and neighbor in node_ids:
            queue.append(neighbor)

unreachable = node_ids - visited
if unreachable:
    print(f'Unreachable nodes: {unreachable}')
else:
    print('All nodes reachable from Start')

# Show paths to End
paths_to_end = [e['from'] for e in edges if e['to'] == 'End']
print(f'Paths to End: {len(paths_to_end)} ({paths_to_end})')
"
